inline int PhongThanCatalogSetEffect(int detail,int row,int part,int level){
 // Original warrior family 310 is white (no blue modifiers or set ID).
 // It shares names/icons with families 311+, so name matching cannot infer a set.
 if(part==310)return 0;
 int lo=0,hi=sizeof(ptSetCatalog)/sizeof(ptSetCatalog[0])-1;
 while(lo<=hi){int m=(lo+hi)/2;const PhongThanSetCatalogIdentity& v=ptSetCatalog[m];if(v.detail<detail||(v.detail==detail&&v.row<row))lo=m+1;else if(v.detail>detail||(v.detail==detail&&v.row>row))hi=m-1;else return v.part==part&&v.level==level?v.effect:0;}return 0;
}
